#!/usr/bin/env bash
# sync-canon-copies.sh — regenerate the canon copies that the agentic layer's skills load,
# from this working tree's docs/.
#
# One script, one copy of the read / link-rewrite / provenance-header logic, driven by the
# TARGETS table below. Every file under agentic/skills/shared/references/ that mirrors living-doc
# canon is generated by this script and verified in CI (.github/workflows/agentic-tests.yml) —
# none of them is hand-maintained, and a hand edit fails the build.
#
# Why the copies exist at all: `npx skills add` copies only a skill's folder and `shared`'s into
# the user's project, where this repository's docs/ does not exist. So the skills read the copy
# next to them. The copies cannot drift, because the source is the same commit's docs/ and CI
# diffs the result.
#
# Both canon sources live at docs/guides/ today. A later change relocates them under
# docs/reference/ — when that lands, update the source paths in TARGETS below (and the
# link-rewriting rules, which assume each source and its cross-references live under docs/guides/
# and docs/examples/). The relocation affects BOTH targets, not just one.
#
# Usage:
#   agentic/scripts/sync-canon-copies.sh              # every target
#   agentic/scripts/sync-canon-copies.sh <target>
#   agentic/scripts/sync-canon-copies.sh all
#   agentic/scripts/sync-canon-copies.sh --list
#
# <target> is a key in TARGETS below (glossary | bdd-schemas), or "all" for every target.
# There is no ref argument: the source is always this working tree, so the copies match the
# commit they are committed in. Nothing is fetched over the network.
#
# Exits 1 if the target is unknown, or a source page is missing or empty.

set -euo pipefail

LAYER_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPO_ROOT="$(cd "${LAYER_ROOT}/.." && pwd)"
LIVING_DOC_REPO="AbsaOSS/living-doc"
REFERENCES_DIR="skills/shared/references"

# Links in a generated copy must resolve from a user's project, which has no living-doc checkout
# around it, so the canon's relative links are rewritten to absolute URLs on this branch.
BLOB_BASE="https://github.com/${LIVING_DOC_REPO}/blob/master"

# ── Target table: canon path → copy path ─────────────────────────────────────
# Each row is "<target>|<canon path, relative to the repo root>|<copy path, relative to LAYER_ROOT>".
# A plain indexed array rather than an associative one: macOS ships bash 3.2, which has no
# `declare -A`, and contributors run this script locally as well as in CI.
TARGETS=(
  "glossary|docs/guides/living-doc-glossary.md|${REFERENCES_DIR}/living-doc-glossary.md"
  "bdd-schemas|docs/guides/living-doc-header-types.md|${REFERENCES_DIR}/living-doc-bdd-schemas.md"
)

target_names() {
  local row
  for row in "${TARGETS[@]}"; do
    printf '%s\n' "${row%%|*}"
  done
}

# Echo the "<source>|<dest>" pair for a target name, or nothing if it is unknown.
target_row() {
  local row name="$1"
  for row in "${TARGETS[@]}"; do
    if [ "${row%%|*}" = "${name}" ]; then
      printf '%s' "${row#*|}"
      return 0
    fi
  done
  return 1
}

# ── Layer-local addenda ──────────────────────────────────────────────────────
# Content that is NOT canon but that the local copy needs — pointers to files that exist only
# in the agentic layer. Emitted verbatim at the end of the generated file, so it is reproduced
# byte for byte on every re-sync and CI's diff stays clean. Keep this strictly to layer-local
# pointers: anything that restates canon belongs in docs/, not here.
local_addendum() {
  case "$1" in
    bdd-schemas)
      cat <<'ADDENDUM'

---

## Layer-local additions

*Not part of the canon above — contracts and formats that belong to the agentic layer.*

**Formats owned by the layer:** the Project Profile, `seed.yaml` and `manifest.json` formats, and
the matrix of what each skill creates or consumes, are documented in
[agentic-formats.md](./agentic-formats.md).

**Schema reference:** for JSON schema validation, see the [schemas/](./schemas/) directory:

- [project-profile.schema.json](./schemas/project-profile.schema.json) — Project Profile validation
- [seed.schema.json](./schemas/seed.schema.json) — seed.yaml validation
- [manifest.schema.json](./schemas/manifest.schema.json) — manifest.json validation
ADDENDUM
      ;;
    *) : ;;
  esac
}

usage() {
  echo "Usage: $0 [<target>|all]" >&2
  echo "       $0 --list" >&2
  echo "  <target>: one of: $(target_names | tr '\n' ' ')| all (default: all)" >&2
  echo "  The source is always this working tree's docs/ — there is no ref argument." >&2
}

if [ "${1:-}" = "--list" ]; then
  printf '%s\n' "${TARGETS[@]}" | tr '|' '\t'
  exit 0
fi

if [ "${1:-}" = "--help" ] || [ "${1:-}" = "-h" ]; then
  usage
  exit 0
fi

TARGET="${1:-all}"

if [ "${TARGET}" != "all" ] && ! target_row "${TARGET}" >/dev/null; then
  echo "Error: unknown target '${TARGET}'" >&2
  usage
  exit 1
fi

TMP_FILE="$(mktemp)"
trap 'rm -f "${TMP_FILE}" "${TMP_FILE}.rewritten"' EXIT

sync_one() {
  local target="$1" row source_path dest_rel source dest
  row="$(target_row "${target}")"
  source_path="${row%%|*}"
  dest_rel="${row#*|}"
  source="${REPO_ROOT}/${source_path}"
  dest="${LAYER_ROOT}/${dest_rel}"

  echo "Reading ${source_path} from this working tree ..." >&2
  if [ ! -f "${source}" ]; then
    echo "Error: canon page not found: ${source_path}" >&2
    echo "If the page moved, update the source path for '${target}' in TARGETS." >&2
    exit 1
  fi

  if [ ! -s "${source}" ]; then
    echo "Error: ${source_path} is empty — refusing to overwrite ${dest_rel}" >&2
    exit 1
  fi

  # Rewrite the canon's relative links to absolute living-doc URLs so the copy reads correctly
  # from a project that has no living-doc checkout. Same-page anchors (#section) are left
  # untouched, as are already-absolute links (http/https) — none of the patterns below can match
  # those, since each requires "(" to be followed immediately by a slash-free, colon-free
  # relative segment. Handled shapes, generic rather than a fixed filename list so a newly-added
  # sibling doc or example asset in the source needs no change here:
  #   - "(../foo)"      — parent-relative, resolves under docs/ (each source lives in docs/guides/)
  #   - "(./foo)"       — explicit same-dir relative, resolves under docs/guides/
  #   - "(foo.md)"      — bare sibling filename (no path separator), resolves under docs/guides/
  sed -E \
    -e "s|\(\.\./([^)]+)\)|(${BLOB_BASE}/docs/\1)|g" \
    -e "s|\(\./([^)]+)\)|(${BLOB_BASE}/docs/guides/\1)|g" \
    -e "s|\(([A-Za-z0-9_.-]+\.md)(#[^)]*)?\)|(${BLOB_BASE}/docs/guides/\1\2)|g" \
    "${source}" > "${TMP_FILE}"

  {
    echo "<!-- generated from ${source_path} by agentic/scripts/sync-canon-copies.sh — do not edit -->"
    echo "<!-- Generated file — do not edit by hand. CI re-runs the sync and fails on any diff. -->"
    echo
    cat "${TMP_FILE}"
    local_addendum "${target}"
  } > "${dest}"

  echo "Wrote $(wc -l < "${dest}") lines to agentic/${dest_rel}" >&2
}

if [ "${TARGET}" = "all" ]; then
  for t in $(target_names); do
    sync_one "$t"
  done
else
  sync_one "${TARGET}"
fi
